 {page==='People'&&<>{reportSelection&&<div className="policy-note"><Info size={14}/><span>Report filter: {reportSelection.label}</span><button onClick={()=>{setReportSelection(null);setPersonLocation('');setPersonDivision('');setFilter('All')}}>Clear report filter</button></div>}<div className="toolbar"><div className="search"><Search size={17}/><input aria-label="Search directory" placeholder="Search people, role, department…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Filter department" value={filter} onChange={e=>setFilter(e.target.value)}><option value="All">All departments</option>{[...new Set(people.map(p=>p.department||'Unassigned'))].map(d=><option key={d}>{d}</option>)}</select>{admin&&<><select aria-label="Filter employment group" value={personEmployment} onChange={e=>setPersonEmployment(e.target.value)}><option value="Current">Current employees</option><option value="Former">Former / archived employees</option></select><select aria-label="Filter login access" value={personLogin} onChange={e=>setPersonLogin(e.target.value)}><option value="All">All login access</option><option value="Enabled">Login enabled</option><option value="Disabled">Login disabled / not activated</option></select></>}<select aria-label="Filter location" value={personLocation} onChange={e=>setPersonLocation(e.target.value)}><option value="">All locations</option>{[...new Set(people.map(p=>p.location||'Unassigned'))].map(d=><option key={d}>{d}</option>)}</select><select aria-label="Filter division" value={personDivision} onChange={e=>setPersonDivision(e.target.value)}><option value="">All divisions</option>{[...new Set(people.map(p=>p.division||'Unassigned'))].map(d=><option key={d}>{d}</option>)}</select><span className="result-count">{matchedPeople.length} {personEmployment==='Former'?'former':'current'} {matchedPeople.length===1?'person':'people'} in this view</span>{data.importSummary&&admin&&<button className="subtle" onClick={()=>setIncludeDemo(!includeDemo)}>{includeDemo?'Hide demo profiles':'Include demo profiles'}</button>}<div className="segment">{['List','Directory','Org chart'].map(v=><button key={v} className={peopleView===v?'active':''} disabled={v==='Org chart'&&personEmployment==='Former'} onClick={()=>setPeopleView(v)}>{v}</button>)}</div></div>{peopleView==='Org chart'&&personEmployment!=='Former'?<OrganizationChart people={matchedPeople as PersonRecord[]} onPerson={p=>{setPerson(people.find(x=>x.id===p.id)??null);setModal('profile')}}/>:peopleView==='List'||personEmployment==='Former'?<section className="panel"><div className="table-wrap"><table><thead><tr><th>Name</th><th>Department</th><th>Division</th><th>Location</th><th>Employment</th><th>Hire date</th><th>Work contact</th></tr></thead><tbody>{matchedPeople.map((p,i)=><tr key={p.id}><td><button className="person-row-button" onClick={()=>{setPerson(p);setModal('profile')}}><Avatar name={p.name} person={p} index={i} small/><span><strong>{p.name}</strong><small>{p.title}{p.demo?' · Demo':''}{p.review_flag==='possible-test-account'?' · Possible test account':''}{directoryActive(p as PersonRecord)?' · Current employee':' · Former employee'}{!p.active?' · Login disabled':''}</small></span></button></td><td>{p.department}</td><td>{p.division||'Unassigned'}</td><td>{p.location}</td><td>{p.employment}</td><td>{formatDate(p.hire_date)}</td><td>{admin&&p.source_email?<><a href={'mailto:'+encodeURIComponent(p.source_email)}>{p.source_email}</a><small>{p.directory_phone||'No source phone'} · HR-only source contact</small></>:p.work_phone||'Not shared'}</td></tr>)}</tbody></table></div></section>:<div className="people-grid">{matchedPeople.map((p,i)=><button className="person-card" key={p.id} onClick={()=>{setPerson(p);setModal('profile')}}><div className="person-card-top"><Avatar name={p.name} person={p} index={i}/>{!p.active?<span className="demo-tag">LOGIN DISABLED</span>:p.demo?<span className="demo-tag">DEMO</span>:<span className="status-dot"/>}</div><h3>{p.name}</h3><p>{p.title}</p><small>{directoryActive(p as Parameters<typeof directoryActive>[0])?'Current employee':'Former employee'}</small><span className="department-pill">{p.department}</span><div className="person-card-footer"><span><MapPin size={13}/>{p.location}</span><ArrowUpRight size={15}/></div></button>)}</div>}{matchedPeople.length===0&&<div className="empty"><Search/><strong>No matching people</strong><p>Try another location, division or department.</p></div>}</>}
