 {page==='My profile'&&<section className="panel"><EmployeeProfile titleId="my-profile-title" employeeId={me.id} me={me} people={people} onSaved={refresh} onManageAccess={()=>{setPerson(me);setModal('access')}} onManageBudget={()=>{setPerson(me);setModal('budget')}}/></section>}
